-- Migration 0040_docket: generated by drizzle-kit (tables, keys, indexes), RLS, the column-list SET NULL actions, the scope guards and the closed_by guard hand-written, reviewed before commit.
-- Reviewed-by: Claude (agent, #347)
-- The docket (#347, part 4 of #32; ADR 0013):
--   * listing, hearing, appearance, order, obligation, task: tenant tables (tenantTable()) under
--     FORCE RLS with ws_isolation (tenantPolicy()); all but appearance carry provenance() and
--     provenanceCheck(). Grants come from the default privileges (app: 02-roles.sql, clerk: 0022).
--   * listing_one_canonical_uq: at most one canonical listing (the next date) per proceeding. The
--     index is immediate, so a flip runs unset-old then set-new inside one transaction.
--   * listing.hall_id, listing.bench_id and order.bench_id are single-column FKs into the
--     global-or-workspace court tables, guarded by app_reference_scope_guard in mode same_or_global.
--   * Member references (appearance.member_id, obligation.owner_member_id, obligation.closed_by,
--     task.owner_member_id) and optional fact links (listing.source_document_id,
--     obligation.source_order_id, task.fulfils_obligation_id) are ON DELETE SET NULL (<column>)
--     (Postgres 15+): drizzle-kit writes a plain SET NULL, which would also null the NOT NULL
--     workspace_id; its snapshot keeps `set null`. Facts keep the proceeding, matter, document and
--     anchor they cite (NO ACTION); appearances cascade with their hearing.
--   * obligation_closure_chk: a closed obligation (done, not_applicable, superseded) needs a
--     closed_reason_type and closed_at, and not_applicable a non-blank closed_note.
--     app_obligation_closed_by_guard() (BEFORE INSERT/UPDATE) also requires closed_by on a closed
--     row (23514). Only the closed_by FK's SET NULL passes: account deletion cascades the closer's
--     member row, and that referential action runs nested (pg_trigger_depth() > 1) on a row whose
--     closed_by was set.
-- Expand only: new tables, a function and triggers.
CREATE TABLE "appearance" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"hearing_id" uuid NOT NULL,
	"member_id" uuid,
	"capacity" "appearance_capacity" NOT NULL,
	"appearing_for_person_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "appearance_workspace_id_id_uq" UNIQUE("workspace_id","id")
);
