CREATE FUNCTION app_obligation_closed_by_guard() RETURNS trigger
  LANGUAGE plpgsql SECURITY INVOKER SET search_path = public, pg_temp
  AS $$
  BEGIN
    IF NEW.status = 'open' OR NEW.closed_by IS NOT NULL THEN
      RETURN NEW;
    END IF;
    -- The closed_by FK's SET NULL (the closer's member row deleted): a nested referential action.
    IF TG_OP = 'UPDATE' AND OLD.closed_by IS NOT NULL AND pg_trigger_depth() > 1 THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION 'obligation: a % obligation needs closed_by', NEW.status
      USING ERRCODE = 'check_violation';
  END
  $$;--> statement-breakpoint
